        this.addAnnotation((ENamedElement)this.getSwServiceProps_SwServiceReentrance(), source, new String[]{"documentation", "Reentrance enables or prohibits the service to be invoked again, before the service has\r\nfinished and delivered a result. If the attribute is missing, then reentrance is prohibited."});
        this.addAnnotation((ENamedElement)this.getSwServiceProps_SwImplPolicy(), source, new String[]{"documentation", "Enables the specification of an implementation strategy. In this way, the direction of the implementation to come, can be specified in advance in an earlier phase."});
