        this.addAnnotation((ENamedElement)this.swServiceImplPolicyEnumEEnum.getELiterals().get(0), source, new String[]{"documentation", "Standard service and default value, if nothing is defined."});
        this.addAnnotation((ENamedElement)this.swServiceImplPolicyEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "inline service definition."});
