        this.addAnnotation((ENamedElement)this.swServiceImplPolicyEnumEEnum.getELiterals().get(3), source, new String[]{"documentation", "The service (in AUTOSAR: BswModuleEntry) is implemented in a way that it either resolves to an inline function or to a standard function depending on conditions set at a later point in time.\r\n\r\nThis could be handled by using the AUTOSAR compiler abstraction macro INLINE and/or by further compiler switches depending on ECU configuration values."});
